-- both columns, correct semantics each:
-- SELECT region, sale_date, amount, ... region_total, ... running_total
-- FROM sales;

function runningTotal(rows){
  // rows pre-sorted by region, then sale_date (contiguous partitions)
  const out = [];
  let acc = 0;
  for (const r of rows){
    acc += r.amount;
    out.push({ region: r.region, date: r.date, running: acc });
  }
  return out;
}

